\begin{aligned}
\mathrm{IsNatural}(\eta,F,G)\leftrightarrow\exists\alpha\ \bigl(&\eta=(F,G,\alpha)\land
\alpha\in\prod_{A\in\mathrm{Ob}(\mathcal C)}\mathrm{Hom}_{\mathcal D}(F(A),G(A))\\
&\land\forall A,B\in\mathrm{Ob}(\mathcal C)\ \forall f\in\mathrm{Hom}_{\mathcal C}(A,B)\
(G(f)\circ\alpha(A)=\alpha(B)\circ F(f))\bigr).
\end{aligned}
